package com.rpb.reservation.workforce;
import com.rpb.reservation.workforce.scheduling.*;import com.rpb.reservation.workforce.scheduling.restswap.*;import com.rpb.reservation.workforce.scheduling.bulk.*;import com.rpb.reservation.workforce.calendar.*;import com.rpb.reservation.workforce.application.*;import com.rpb.reservation.workforce.attendance.AttendanceAccess;import com.rpb.reservation.workforce.domain.WorkforceException;
import static com.rpb.reservation.workforce.scheduling.restswap.RestSwapDtos.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class WorkforceRestSwapPostgresTest extends WorkforcePostgresTest {
 RestSwapPlanService plans;RestSwapService swaps;RestSwapRepository rests;ScheduleService schedules;SchedulingRepository planning;CalendarService calendar;UUID employee,shift;LocalDate rest=LocalDate.of(2026,11,2),makeup=LocalDate.of(2026,11,7);
 @BeforeEach void setupSwap(TestInfo info){if(info.getTestMethod().orElseThrow().getDeclaringClass()!=WorkforceRestSwapPostgresTest.class)return;var json=new WorkforceJson(new com.fasterxml.jackson.databind.ObjectMapper().findAndRegisterModules());var audit=new WorkforceAudit(logs,new com.fasterxml.jackson.databind.ObjectMapper().findAndRegisterModules());planning=new SchedulingRepository(jdbc,json);schedules=proxy(new ScheduleService(access,planning,repository,audit,clock));var shifts=proxy(new ShiftService(access,planning,audit));shift=UUID.randomUUID();shifts.save(admin,store,shift,new SchedulingDtos.ShiftWrite(0L,"Day","09:00","18:00",false,"none",0,0,0,0,false,true));employee=UUID.randomUUID();employees.save(admin,store,employee,command(0,List.of(store),company,null,null));calendar=proxy(new CalendarService(access,new AttendanceAccess(access,repository,planning),planning,new CalendarRepository(jdbc),audit));calendar.save(admin,store,UUID.randomUUID(),new CalendarDtos.CalendarWrite(0L,rest,"store_rest","店休",true));rests=new RestSwapRepository(jdbc);var bulk=new BulkScheduleRepository(jdbc,json);plans=proxy(new RestSwapPlanService(access,planning,bulk,rests,new CalendarRepository(jdbc),json,clock));swaps=proxy(new RestSwapService(access,planning,bulk,repository,rests,plans,schedules,audit,json));}
 Request request(){return new Request(List.of(employee),rest,makeup,shift);}
 @Test void subsequentMakeupDateChangeIsVisibleAndDoesNotRewriteTransferHistory(){var p=plans.preview(admin,store,request());var result=swaps.commit(admin,store,UUID.randomUUID(),new Commit(request(),p.fingerprint()));var id=result.scheduleIds().getFirst();var old=planning.find(tenant,id).orElseThrow();schedules.save(admin,store,id,new SchedulingDtos.ScheduleWrite(old.version(),employee,shift,makeup.plusDays(1),"scheduled"));var link=rests.list(tenant,store,rest,makeup,employee).getFirst();assertThat(link.makeupDate()).isEqualTo(makeup);assertThat(link.makeupStatus()).isEqualTo("changed");}
 @Test void calendarStaffOnlySeesOwnTransferAndOtherStoresSeeNone(){var p=plans.preview(admin,store,request());swaps.commit(admin,store,UUID.randomUUID(),new Commit(request(),p.fingerprint()));UUID account=account("store_staff",Set.of(store),Set.of("workforce.view"));jdbc.update("update workforce_employees set account_id=? where tenant_id=? and id=?",account,tenant,employee);var staff=new com.rpb.reservation.walkin.api.CurrentActor(tenant,account,"staff",Set.of("store_staff"),Set.of("workforce.view"),Set.of(store));assertThat(calendar.list(staff,store,rest,makeup).restSwaps()).extracting(Link::employeeId).containsExactly(employee);assertThat(calendar.list(admin,sibling,rest,makeup).restSwaps()).isEmpty();}
 @Test void leaveConflictAndMixedEmployeeBatchSkipWithoutChangingOriginal(){var source=schedules.save(admin,store,UUID.randomUUID(),new SchedulingDtos.ScheduleWrite(0L,employee,shift,rest,"scheduled"));UUID type=UUID.randomUUID();jdbc.update("insert into workforce_leave_types(id,tenant_id,store_id,name,paid,enabled,version) values(?,?,?,'Leave',true,true,1)",type,tenant,store);jdbc.update("insert into workforce_leaves(id,tenant_id,store_id,schedule_id,employee_id,type_id,type_name,paid,start_at,end_at,reason,status,applicant_id,version) values(?,?,?,?,?,?,'Leave',true,?,?, 'test','pending',?,1)",UUID.randomUUID(),tenant,store,source.id(),employee,type,java.sql.Timestamp.from(source.startAt()),java.sql.Timestamp.from(source.endAt()),adminId);UUID second=UUID.randomUUID();jdbc.update("insert into workforce_employees(id,tenant_id,employee_no,name,job_title,hire_date,status,company_id,company_effective_date,main_store_id,version) values(?,?,'E002','Bob','Service','2026-10-01','active',?,'2026-10-01',?,1)",second,tenant,company,store);jdbc.update("insert into workforce_work_stores(tenant_id,employee_id,store_id,started_on) values(?,?,?,'2026-10-01')",tenant,second,store);var request=new Request(List.of(employee,second),rest,makeup,shift);var p=plans.preview(admin,store,request);assertThat(p.ready()).isEqualTo(1);assertThat(p.conflicts()).isEqualTo(1);assertThat(p.items()).filteredOn(i->i.employeeId().equals(employee)).singleElement().extracting(Item::reason).isEqualTo("IN_USE");var result=swaps.commit(admin,store,UUID.randomUUID(),new Commit(request,p.fingerprint()));assertThat(result.changed()).isEqualTo(1);assertThat(result.skipped()).isEqualTo(1);assertThat(planning.find(tenant,source.id()).orElseThrow().status()).isEqualTo("scheduled");}
 @Test void previewThenMovesUnclockedWorkAndRetainsOriginalAndReplays(){var old=schedules.save(admin,store,UUID.randomUUID(),new SchedulingDtos.ScheduleWrite(0L,employee,shift,rest,"scheduled"));var preview=plans.preview(admin,store,request());assertThat(preview.ready()).isEqualTo(1);assertThat(preview.items().getFirst().cancelSchedules()).containsExactly(old.id());UUID command=UUID.randomUUID();var c=new Commit(request(),preview.fingerprint());var result=swaps.commit(admin,store,command,c);assertThat(result.changed()).isEqualTo(1);assertThat(planning.find(tenant,old.id()).orElseThrow().status()).isEqualTo("cancelled");assertThat(planning.find(tenant,result.scheduleIds().getFirst()).orElseThrow().workDate()).isEqualTo(makeup);assertThat(swaps.commit(admin,store,command,c)).isEqualTo(result);assertThat(rests.list(tenant,store,rest,makeup,employee)).hasSize(1);assertThat(plans.preview(admin,store,request()).conflicts()).isEqualTo(1);}
 @Test void existingMakeupScheduleIsNotOverwrittenAndSourceChangeRejects(){var preview=plans.preview(admin,store,request());var old=schedules.save(admin,store,UUID.randomUUID(),new SchedulingDtos.ScheduleWrite(0L,employee,shift,makeup,"scheduled"));assertThatThrownBy(()->swaps.commit(admin,store,UUID.randomUUID(),new Commit(request(),preview.fingerprint()))).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(409);assertThat(plans.preview(admin,store,request()).items().getFirst().reason()).isEqualTo("EXISTING_MAKEUP");assertThat(planning.find(tenant,old.id()).orElseThrow().version()).isEqualTo(1);}
 @Test void attendancePreventsCancelAndAuditFailureRollsBack(){var source=schedules.save(admin,store,UUID.randomUUID(),new SchedulingDtos.ScheduleWrite(0L,employee,shift,rest,"scheduled"));jdbc.update("insert into workforce_attendance_sessions(id,tenant_id,store_id,employee_id,schedule_id,in_at,out_at,version) values(?,?,?,?,?,?,?,1)",UUID.randomUUID(),tenant,store,employee,source.id(),java.sql.Timestamp.from(source.startAt()),java.sql.Timestamp.from(source.endAt()));assertThat(plans.preview(admin,store,request()).items().getFirst().reason()).isEqualTo("IN_USE");var isolated=new Request(List.of(employee),LocalDate.of(2026,11,9),LocalDate.of(2026,11,14),shift);calendar.save(admin,store,UUID.randomUUID(),new CalendarDtos.CalendarWrite(0L,isolated.restDate(),"store_rest","店休",true));var p=plans.preview(admin,store,isolated);doThrow(new IllegalStateException("audit failed")).when(logs).append(any(com.rpb.reservation.common.scope.StoreScope.class),any());assertThatThrownBy(()->swaps.commit(admin,store,UUID.randomUUID(),new Commit(isolated,p.fingerprint()))).isInstanceOf(IllegalStateException.class);assertThat(rests.list(tenant,store,isolated.restDate(),isolated.makeupDate(),employee)).isEmpty();assertThat(planning.list(tenant,store,isolated.makeupDate(),isolated.makeupDate(),employee,20,0)).isEmpty();}
 @Test void closureRequiredAndUnmanagedStoreAndForeignEmployeeDenied(){assertThatThrownBy(()->plans.preview(admin,sibling,request())).isInstanceOf(WorkforceException.class);assertThatThrownBy(()->plans.preview(admin,store,new Request(List.of(UUID.randomUUID()),rest,makeup,shift))).isInstanceOf(WorkforceException.class);assertThatThrownBy(()->plans.preview(admin,store,new Request(List.of(employee),rest.plusDays(1),makeup,shift))).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(400);var worker=new com.rpb.reservation.walkin.api.CurrentActor(tenant,adminId,"staff",Set.of("store_staff"),Set.of("workforce.view"),Set.of(store));assertThatThrownBy(()->plans.preview(worker,store,request())).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(403);}
}



